INSERT INTO [CAMPAGNE_ISCRIZIONI] ([CLASS], [ID], [UPDATECOUNT], [DX], [UPDTIMESTAMP], [STAGIONECLASS], [STAGIONEID], [NOTE_ISCRIZIONE], [SCONTO_FRATELLI], [SCADENZA_SCONTO], [INIZIO], [FINE], [QUOTA_ASSOCIATIVA], [SCONTO_RATA_UNICA], [FLAG_ATT_SPORTIVA], [PERC_SCONTO_FRATELLI]) VALUES ('TISCampagnaIscrizione', '6A1A8A7B439F424FB3555B2CD288B101', 0, 'A.S. 23/24 ISCRIZIONE CORSI', '2023-11-02T12:32:41.633', 'TISStagione', '23/24', 'NON rispondere a questo email -- in caso di informazioni scrivere a&nbsp;<b>email@gmail.com</b><br><br>l''Iscrizione sarà attiva solo a seguito del pagamento della quota, vi chiediamo di inviare copia del bonifico eseguito by email a&nbsp;<b>email@gmail.com</b><br><br>&nbsp;<br>Il pagamento a favore di SOCIETA'' potrà avvenire a mezzo:<ul><li>Bonifico (Iban IT 00 S 00000 00000 000000000000) -&nbsp;<u>indicando nella causale COGNOME-NOME e ANNO di nascita dell''atleta</u></li></ul><p>Per accedere alle attività sportive&nbsp;<u>è OBBLIGATORIO consegnare il certificato medico in corso di validità,</u>&nbsp;senza tale documento non sarà permessa l''attività sportiva all''atleta.</p><br>Vi ringraziamo fin da ora per la Vostra cortese collaborazione&nbsp;<br><br>', 50.00, 1, '2023-07-01T00:00:00', '2024-06-30T00:00:00', 0.00, NULL, 0, 0);
